macro.command:
// Basarios Carapace - Guts (MidiQOL isDamaged / Foundry v12 / dnd5e 4.4)
// When damage would drop you to 0 HP (not killed outright), set HP to 1 instead.
// Cooldown: 2 days (worldTime). While on cooldown the transfer AE is disabled.

const TWO_DAYS = 172800;
const actorDoc = actor ?? item?.actor ?? item?.parent;
if (!actorDoc || !item) return;

const now = game.time?.worldTime ?? 0;
const readyAt = Number(foundry.utils.getProperty(item, "flags.world.rune.gutsReadyAt") ?? 0);
const macroPass = String(args?.[0]?.macroPass ?? "").toLowerCase();

const findGutsAe = () =>
  actorDoc.effects.find((e) => e.origin === item.uuid && /guts/i.test(e.name ?? ""));

const markSpent = async () => {
  await item.setFlag("world", "rune.gutsReadyAt", now + TWO_DAYS);
  const max = Math.max(1, Number(item.system?.uses?.max ?? 1));
  await item.update({ "system.uses.spent": max });
  const ae = findGutsAe();
  if (ae && !ae.disabled) await ae.update({ disabled: true });
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor: actorDoc }),
    content: `<div class="dnd5e2"><p><strong>Guts</strong> saves ${actorDoc.name} at 1 HP. Can't be used again for 2 days.</p></div>`,
  });
};

// Refresh cooldown when AE applies / item equipped (DAE "on")
if (args?.[0] === "on") {
  if (readyAt && now >= readyAt) {
    await item.setFlag("world", "rune.gutsReadyAt", 0);
    await item.update({ "system.uses.spent": 0 });
    const ae = findGutsAe();
    if (ae?.disabled) await ae.update({ disabled: false });
  } else if (readyAt && now < readyAt) {
    const ae = findGutsAe();
    if (ae && !ae.disabled) await ae.update({ disabled: true });
  }
  return;
}

if (!macroPass.includes("isdamaged")) return;
if (readyAt && now < readyAt) return;

const spent = Number(item.system?.uses?.spent ?? 0);
const max = Number(item.system?.uses?.max ?? 1) || 1;
if (spent >= max) return;

const hp = Number(actorDoc.system?.attributes?.hp?.value ?? 0);
const totalDamage = Number(
  args?.[0]?.totalDamage
  ?? args?.[0]?.damageDetail?.reduce?.((s, d) => s + (Number(d.damage) || 0), 0)
  ?? workflow?.damageTotal
  ?? 0,
);

// Instant death / massive damage: skip (HP max overflow killed outright)
const hpMax = Number(actorDoc.system?.attributes?.hp?.max ?? 0);
if (totalDamage >= hp + hpMax) return;

if (hp > 0 && totalDamage >= hp) {
  // Reduce applied damage so remaining HP is 1
  const keep = hp - 1;
  if (args?.[0]) {
    args[0].totalDamage = keep;
    if (typeof args[0].di === "number") args[0].di = keep;
  }
  await actorDoc.update({ "system.attributes.hp.value": 1 });
  await markSpent();
}
